1	package claudecode
2	
3	import (
4		"bytes"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"log/slog"
10		"os"
11		"os/exec"
12		"strings"
13	
14		"github.com/entireio/cli/cmd/entire/cli/agent"
15		"github.com/entireio/cli/cmd/entire/cli/logging"
16	)
17	
18	const streamEventTypeSystem = "system"
19	
20	// GenerateTextStreaming runs the Claude CLI in stream-json mode, dispatches
21	// progress events to the optional callback, and returns the final result text.
22	// Implements the agent.StreamingTextGenerator interface.
23	//
24	// If the CLI rejects the stream-json flags (older Claude CLI), this falls back
25	// to the non-streaming GenerateText path — without progress events.
26	func (c *ClaudeCodeAgent) GenerateTextStreaming(
27		ctx context.Context,
28		prompt, model string,
29		progress agent.ProgressFn,
30	) (string, error) {
31		if model == "" {
32			model = "haiku"
33		}
34	
35		commandRunner := c.CommandRunner
36		if commandRunner == nil {
37			commandRunner = exec.CommandContext
38		}
39	
40		// Re-inject only the user's apiKeyHelper (via a 0600 file, never argv) so
41		// API-billing auth keeps working under --setting-sources "" isolation —
42		// same contract as GenerateText (see buildGenerateArgs). Best-effort: if
43		// extracting/writing the helper fails, run without it (env/keychain auth
44		// still work) rather than failing the call.
45		settingsPath, cleanup, err := writeAuthSettingsFile(readUserAPIKeyHelper())
46		if err != nil {
47			settingsPath = ""
48		}
49		if cleanup != nil {
50			defer cleanup()
51		}
52	
53		cmd := commandRunner(ctx, "claude", buildStreamingGenerateArgs(model, settingsPath)...)
54	
55		cmd.Dir = os.TempDir()
56		cmd.Env = agent.StripGitEnv(os.Environ())
57		cmd.Stdin = strings.NewReader(prompt)
58	
59		stdout, err := cmd.StdoutPipe()
60		if err != nil {
61			return "", fmt.Errorf("claude stream stdout pipe: %w", err)
62		}
63		var stderr bytes.Buffer
64		cmd.Stderr = &stderr
65	
66		if err := cmd.Start(); err != nil {
67			return "", fmt.Errorf("claude stream start: %w", err)
68		}
69	
70		// Count stdout bytes so the timeout diagnostic can distinguish "provider
71		// produced no output" from "was generating output when killed".
72		counted := &countingReader{r: stdout}
73		final, malformed, parseErr := streamClaudeResponse(counted, makeProgressDispatcher(progress))
74	
75		// Drain any unread stdout so the subprocess can exit cleanly even if the
76		// scanner aborted early (e.g. bufio.ErrTooLong on an oversized line).
77		// Without this, a blocked pipe would deadlock cmd.Wait().
78		if _, drainErr := io.Copy(io.Discard, counted); drainErr != nil {
79			logging.Debug(ctx, "draining claude stream stdout", slog.String("error", drainErr.Error()))
80		}
81		waitErr := cmd.Wait()
82	
83		if malformed > 0 {
84			logging.Warn(ctx, "skipped malformed claude stream lines", slog.Int("count", malformed))
85		}
86	
87		// Specific envelope error outranks a generic ctx-cancel message.
