101				}
102				return "", fmt.Errorf("claude stream failed: %w", waitErr)
103			}
104			if final.Result == nil {
105				return "", errors.New("claude returned empty result")
106			}
107			if progress != nil {
108				progress(agent.GenerationProgress{
109					Phase:        agent.PhaseDone,
110					OutputTokens: outputTokensFromUsage(final.Usage),
111					DurationMs:   final.DurationMs,
112				})
113			}
114			return *final.Result, nil
