125				sentinel = context.DeadlineExceeded
126			}
127			return "", &agent.TextGenerationError{
128				Err:         sentinel,
129				Stderr:      strings.TrimSpace(stderr.String()),
130				StdoutBytes: counted.n,
131			}
132		}
133	
134		// No envelope: check if the CLI rejected streaming flags (older version).
135		if waitErr != nil {
136			stderrStr := stderr.String()
137			if looksLikeUnrecognizedFlag(stderrStr) {
138				logging.Warn(ctx, "claude CLI rejected stream-json flags; falling back to non-streaming (no progress output)",
139					slog.String("stderr", strings.TrimSpace(stderrStr)))
140				return c.GenerateText(ctx, prompt, model)
141			}
142			if stderrStr != "" {
143				return "", fmt.Errorf("claude stream failed: %s: %w", strings.TrimSpace(stderrStr), waitErr)
144			}
145			return "", fmt.Errorf("claude stream failed: %w", waitErr)
146		}
