154	// envelopeErrorMessage formats an is_error result envelope as a typed
155	// *ClaudeError so the explain layer's formatCheckpointSummaryError branches
156	// (auth / rate-limit / config / cli-missing) map it to actionable user
157	// guidance. The non-streaming path returns *ClaudeError via classifyEnvelopeError;
158	// the streaming path must do the same or users lose the specific remediation
159	// hints (e.g. "Run `claude login` and retry") on the streaming code path.
160	//
161	// exitCode is 0 because envelope errors arrive on stdout while the CLI itself
162	// exits successfully — Claude's is_error envelope semantics distinguish
163	// "operational failure with structured details" from "subprocess crash".
164	func envelopeErrorMessage(final *streamEvent) error {
165		resultText := ""
166		if final.Result != nil {
167			resultText = *final.Result
