173	// stream events into agent.GenerationProgress callbacks. PhaseDone is
174	// emitted by GenerateTextStreaming after cmd.Wait, because it needs data
175	// from the parsed final envelope.
176	func makeProgressDispatcher(progress agent.ProgressFn) func(streamEvent) {
