184		var totalChars int
185		return func(ev streamEvent) {
186			switch {
187			case ev.Type == streamEventTypeSystem && ev.Subtype == "status" && ev.Status == "requesting":
188				progress(agent.GenerationProgress{Phase: agent.PhaseConnecting})
189			case ev.Type == streamEventTypeStreamEvent && ev.Event.Type == "message_start":
