cd /private/tmp/claude-502/-Users-ninawork-entire-devenv-cli/8ab4cc89-30b9-4845-9f64-3ef778e0ac43/scratchpad; cat > v_test.go <<'EOF'
package main

import (
	"context"
	"fmt"
	"os/exec"
	"syscall"
)

func main() {
	// Finding #4: Cancel set on a non-CommandContext cmd fails at Start/Run.
	c1 := exec.Command("echo", "hi") // NOT CommandContext
	c1.Cancel = func() error { return nil }
	err := c1.Run()
	fmt.Printf("#4 non-CommandContext + Cancel -> Run err: %v\n", err)

	// Finding #3: Setsid + Setpgid together -> fork/exec EPERM.
	c2 := exec.CommandContext(context.Background(), "/bin/true")
	c2.SysProcAttr = &syscall.SysProcAttr{Setsid: true, Setpgid: true}
	err = c2.Run()
	fmt.Printf("#3 Setsid+Setpgid -> Run err: %v\n", err)

	// Control: Setsid alone still lets kill(-pid) work (group leader).
	c3 := exec.CommandContext(context.Background(), "/bin/true")
	c3.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
	err = c3.Run()
	fmt.Printf("#3 Setsid alone -> Run err: %v\n", err)
}
EOF
go run v_test.go 2>&1

