1	package agent
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os/exec"
8		"runtime"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	const windowsOS = "windows"
15	
16	func TestRunIsolatedTextGeneratorCLI_EmptyOutput(t *testing.T) {
17		t.Parallel()
18	
19		runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
20			return exec.CommandContext(ctx, "echo", "-n", "")
21		}
22		// On some systems echo -n "" still prints a newline; use printf for reliable empty output
23		if runtime.GOOS != windowsOS {
24			runner = func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
25				return exec.CommandContext(ctx, "printf", "")
26			}
27		}
28		_, _, _, err := RunIsolatedTextGeneratorCLI(context.Background(), runner, "test", "test-agent", nil, "")
29		if err == nil {
30			t.Fatal("expected error for empty output")
31		}
32		if !strings.Contains(err.Error(), "test-agent CLI returned empty output") {
33			t.Fatalf("error = %q, want it to contain %q", err.Error(), "test-agent CLI returned empty output")
34		}
35	}
36	
37	func TestRunIsolatedTextGeneratorCLI_NonZeroExit(t *testing.T) {
38		t.Parallel()
39	
40		runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
41			return exec.CommandContext(ctx, "sh", "-c", "echo 'some error' >&2; exit 1")
42		}
43		_, capturedStderr, stdoutBytes, err := RunIsolatedTextGeneratorCLI(context.Background(), runner, "test", "myagent", nil, "")
44		if err == nil {
45			t.Fatal("expected error for non-zero exit")
46		}
47		errMsg := err.Error()
48		if !strings.Contains(errMsg, "myagent CLI failed (exit 1)") {
49			t.Fatalf("error = %q, want it to contain exit code info", errMsg)
50		}
51		if !strings.Contains(errMsg, "some error") {
52			t.Fatalf("error = %q, want it to contain stderr detail", errMsg)
53		}
54		// The captured-output return values feed the explain timeout diagnostic;
55		// callers wrap them into *TextGenerationError.
56		if capturedStderr != "some error" {
57			t.Fatalf("capturedStderr = %q, want %q", capturedStderr, "some error")
58		}
59		if stdoutBytes != 0 {
60			t.Fatalf("stdoutBytes = %d, want 0 (nothing was written to stdout)", stdoutBytes)
61		}
62	}
63	
64	func TestRunIsolatedTextGeneratorCLI_NonZeroExitFallsBackToStdout(t *testing.T) {
65		t.Parallel()
66	
67		runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
68			return exec.CommandContext(ctx, "sh", "-c", "echo 'stdout detail'; exit 1")
69		}
70		_, capturedStderr, stdoutBytes, err := RunIsolatedTextGeneratorCLI(context.Background(), runner, "test", "myagent", nil, "")
71		if err == nil {
72			t.Fatal("expected error for non-zero exit")
73		}
74		if !strings.Contains(err.Error(), "stdout detail") {
75			t.Fatalf("error = %q, want it to contain stdout as fallback detail", err.Error())
76		}
77		if capturedStderr != "" {
78			t.Fatalf("capturedStderr = %q, want empty (nothing was written to stderr)", capturedStderr)
79		}
80		if stdoutBytes == 0 {
81			t.Fatal("stdoutBytes = 0, want the stdout the CLI produced to be counted")
82		}
83	}
84	
85	func TestRunIsolatedTextGeneratorCLI_BinaryNotFound(t *testing.T) {
86		t.Parallel()
87	
88		_, _, _, err := RunIsolatedTextGeneratorCLI(context.Background(), nil, "nonexistent-binary-12345", "myagent", nil, "")
89		if err == nil {
90			t.Fatal("expected error for missing binary")
91		}
92		if !strings.Contains(err.Error(), "myagent CLI not found") {
93			t.Fatalf("error = %q, want it to contain 'not found'", err.Error())
94		}
95	}
96	
97	func TestRunIsolatedTextGeneratorCLI_NilRunnerDefaultsToExec(t *testing.T) {
98		t.Parallel()
99	
100		// With nil runner, it defaults to exec.CommandContext, so "echo" should work
101		result, _, _, err := RunIsolatedTextGeneratorCLI(context.Background(), nil, "echo", "echo", []string{"hello"}, "")
102		if err != nil {
103			t.Fatalf("unexpected error: %v", err)
104		}
105		if result != "hello" {
106			t.Fatalf("result = %q, want %q", result, "hello")
107		}
108	}
109	
110	func TestRunIsolatedTextGeneratorCLI_CanceledContextPreservesSentinel(t *testing.T) {
111		t.Parallel()
112	
113		if runtime.GOOS == windowsOS {
114			t.Skip("uses POSIX shell command")
115		}
116	
117		runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
118			return exec.CommandContext(ctx, "sh", "-c", "sleep 10")
119		}
120	
121		ctx, cancel := context.WithCancel(context.Background())
122		go func() {
123			time.Sleep(10 * time.Millisecond)
124			cancel()
125		}()
126	
127		_, _, _, err := RunIsolatedTextGeneratorCLI(ctx, runner, "test", "test", nil, "")
128		if err == nil {
129			t.Fatal("expected cancellation error")
130		}
131		if !errors.Is(err, context.Canceled) {
132			t.Fatalf("expected context.Canceled, got %v", err)
133		}
134	}
135	
136	func TestRunIsolatedTextGeneratorCLI_DeadlineCarriesPartialOutput(t *testing.T) {
137		t.Parallel()
138	
139		if runtime.GOOS == windowsOS {
140			t.Skip("uses POSIX shell command")
141		}
142	
143		// The CLI produces some output on both streams, then stalls until the
144		// deadline kills it. The sentinel must be preserved AND the captured
145		// evidence returned, so the timeout diagnostic can say "was generating
146		// output when killed" with the real stderr instead of guessing.
147		runner := func(ctx context.Context, _ string, _ ...string) *exec.Cmd {
148			return exec.CommandContext(ctx, "sh", "-c",
149				"echo 'partial output'; echo 'stalled talking to API' >&2; exec sleep 10")
150		}
151		ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)
152		defer cancel()
153	
154		_, capturedStderr, stdoutBytes, err := RunIsolatedTextGeneratorCLI(ctx, runner, "test", "test", nil, "")
155		if !errors.Is(err, context.DeadlineExceeded) {
156			t.Fatalf("expected context.DeadlineExceeded, got %v", err)
157		}
158		if capturedStderr != "stalled talking to API" {
159			t.Fatalf("capturedStderr = %q, want the stderr written before the kill", capturedStderr)
160		}
161		if stdoutBytes == 0 {
162			t.Fatal("stdoutBytes = 0, want the partial stdout to be counted")
163		}
164	}
165	
166	func TestTextGenerationError_PreservesSentinelAndPayload(t *testing.T) {
167		t.Parallel()
168	
169		err := &TextGenerationError{Err: context.DeadlineExceeded, Stderr: "stalled", StdoutBytes: 42}
170	
171		// The explain layer routes timeouts with errors.Is and recovers the
172		// evidence with errors.As; both must survive additional wrapping.
173		wrapped := fmt.Errorf("summary generation failed: %w", err)
174		if !errors.Is(wrapped, context.DeadlineExceeded) {
175			t.Fatal("context.DeadlineExceeded sentinel must survive TextGenerationError.Unwrap")
176		}
177		var genErr *TextGenerationError
178		if !errors.As(wrapped, &genErr) {
179			t.Fatal("errors.As must recover *TextGenerationError through wrapping")
180		}
181		if genErr.Stderr != "stalled" {
182			t.Fatalf("Stderr = %q, want %q", genErr.Stderr, "stalled")
183		}
184		if genErr.StdoutBytes != 42 {
185			t.Fatalf("StdoutBytes = %d, want 42", genErr.StdoutBytes)
186		}
187	}
188	
189	func TestStripGitEnv(t *testing.T) {
190		t.Parallel()
191	
192		env := []string{
193			"HOME=/home/user",
194			"GIT_DIR=/some/dir",
195			"PATH=/usr/bin",
196			"GIT_WORK_TREE=/some/tree",
197			"EDITOR=vim",
198		}
199		filtered := StripGitEnv(env)
200	
201		for _, e := range filtered {
202			if strings.HasPrefix(e, "GIT_") {
203				t.Fatalf("GIT_ variable not stripped: %s", e)
204			}
205		}
206		if len(filtered) != 3 {
207			t.Fatalf("expected 3 entries, got %d: %v", len(filtered), filtered)
208		}
209	}

66		// Deadline must stay strictly below killWaitDelay: that backstop would force
67		// the pipe closed on its own, letting this test pass even if group-kill regressed.
68		select {
69		case <-done:
70		case <-time.After(killWaitDelay / 2):
71			t.Fatal("read did not return after cancellation; the pipe-holding grandchild outlived the group-kill")
72		}
73	}
74	
75	// Cancel must return cleanly *and* actually terminate the leader.
76	func TestKillProcessGroupOnCancel_TerminatesLeader(t *testing.T) {
77		t.Parallel()
78	
79		// exec requires CommandContext when Cancel is non-nil; we invoke Cancel directly.
80		cmd := exec.CommandContext(context.Background(), "/bin/sh", "-c", "sleep 60 & wait")
81		killProcessGroupOnCancel(cmd)
82		if err := cmd.Start(); err != nil {
83			t.Fatalf("start: %v", err)
84		}
85	
86		if err := cmd.Cancel(); err != nil {
87			t.Fatalf("Cancel returned %v; want nil", err)
88		}
89	
90		// Bound the wait ourselves — no WaitDelay is set here, so a group-kill
91		// regression would block on the full 60s sleep instead of failing fast.
92		done := make(chan error, 1)
93		go func() { done <- cmd.Wait() }()
94	
95		select {
96		case err := <-done:
97			if err == nil {
98				t.Error("Wait returned nil; the killed shell should report a termination error")
99			}
100		case <-time.After(killWaitDelay):
101			t.Fatal("Wait did not return after Cancel; the group-kill handler may have regressed")
102		}
103	}

13	// /dev/tty-style probe in the child fails. Sets CREATE_NEW_PROCESS_GROUP and
14	// DETACHED_PROCESS so the child has no console and no signal coupling.
15	func detachFromTTY(cmd *exec.Cmd) {
16		if cmd.SysProcAttr == nil {
17			cmd.SysProcAttr = &syscall.SysProcAttr{}
18		}
19		cmd.SysProcAttr.CreationFlags |= windows.CREATE_NEW_PROCESS_GROUP | windows.DETACHED_PROCESS
20	}

