import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// lockedBuffer is an io.Writer whose contents can be read while writes are
// still in flight. RunIsolatedTextGeneratorCLI reads the captured output on the
// deadline path while os/exec's stdout/stderr copier may still be writing to
// it, so a plain bytes.Buffer would be a data race.
type lockedBuffer struct {
	mu  sync.Mutex
	buf bytes.Buffer
}

func (b *lockedBuffer) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.Write(p) //nolint:wrapcheck // pass-through to bytes.Buffer, which never errors
}

func (b *lockedBuffer) String() string {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.String()
}

func (b *lockedBuffer) Len() int {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.buf.Len()
}

